function ready(){const q=rep(S.sel);let hs=null;for(let h=0;h<48;h++)if(rate(q.x,q.y,S.t+h)>2){hs=h;break}const n=ITEMS.length-miss(),r=wxNow().r;
 $('#ready').innerHTML=`<div class="row" style="border:0;padding:0"><h3 style="margin:0">Readiness checklist</h3>${safe()?'<span class="chip ok">Marked Safe. Your circle can see it</span>':`<span class="chip w">${n} of ${ITEMS.length} ready</span>`}</div><div class="prog"><i style="width:${n/ITEMS.length*100}%"></i></div>`+ITEMS.map((it,i)=>`<div class="row"><span>${it}</span><span class="seg"><button class="${S.chk[i]===1?'on':''}" data-a="chk" data-i="${i}" data-j="1">Have</button><button class="${S.chk[i]===0?'on need':''}" data-a="chk" data-i="${i}" data-j="0">Need</button></span></div>${S.chk[i]===0?`<div class="tip">${rec(i,hs)}${r>=75?' <b>Roads are unsafe now:</b> <a href="#" data-a="help">ask your circle</a> instead.':''}</div>`:''}`).join('')}
