 const o=S.nr.filter(n=>n.t<=S.t).sort((a,b)=>a.pri-b.pri),tx={open:'Their circle has been alerted.',yes:'You committed. Others were told help is coming.',no:'You passed. Moved to other helpers.',done:'Completed. Thank you for showing up.'};
