function i18n(){if(PR.lang!='es')return;const w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentElement&&!/^(SCRIPT|STYLE|PRE|CANVAS)$/.test(n.parentElement.tagName)&&n.nodeValue.trim()?1:2});let n;while(n=w.nextNode()){const raw=n.nodeValue,t=raw.trim();let r=ES[t];if(!r)for(const[p,s]of ESR)if(p.test(t)){r=t.replace(p,s);break}if(r)n.nodeValue=raw.replace(t,r)}$('#q').placeholder='Tu pueblo o condado (p. ej. Cheektowaga, Erie County)'}
