const _help=help;help=function(){_help();if(!(S.req&&!S.req.closed))$('#sheet').insertAdjacentHTML('beforeend','<div class="sm mut" style="margin-top:8px">In immediate danger, call 911. Cold Path never replaces emergency services.</div>');i18n()};
