const _decl=declare;declare=function(type){if(type!='Medical emergency'&&S.reqN>=3){toast('To prevent false alarms, extra requests are reviewed first. In an emergency, call 911.');return}S.reqN++;_decl(type);if(S.req){if(xcOn())lg('Extra-care household flagged');const hh=[PR.hh.kids&&'kids',PR.hh.pets&&'pets',PR.hh.older&&'older adult'].filter(Boolean);if(hh.length)lg('Household: '+hh.join(', '));if(type=='Silent alert')lg('Silent: location shared, no sound');track()}};
const _ans=ans;ans=function(q){return/generator|grill|camp stove|charcoal|propane/.test(q.toLowerCase())&&/indoor|inside|garage|house|heat|basement/.test(q.toLowerCase())?'Never run a generator, grill, or camp stove inside your home, garage, or near windows. Carbon monoxide can kill in minutes. If you feel dizzy, sick or confused, get outside to fresh air and call 911.':_ans(q)};
