 if(/\b\d+\s?(mg|mcg|ml)\b|\bdosage\b|\bdiagnos/i.test(t)&&m.firstChild){m.firstChild.textContent=t='I can’t give medication or medical advice. For symptoms or medicine questions, call your pharmacist or doctor. In an emergency, call 911.'}
