 const src=document.createElement('div');src.className='sm mut';src.style.marginTop='6px';src.textContent='Based on: '+(S.live&&S.live.st=='ok'?'NWS (checked '+ago(S.live.at)+') and ':'')+'storm replay data (simulated, current), shelter list (sample). '+(S.gem=='ok'?'Answered by Gemini.':'');m.appendChild(src);
